function tr(s){var k=s.trim();if(!k)return null;var kn=k.replace(/\s+/g,' ');if(OLD[kn])return s.replace(k,OLD[kn]);if(OLD[k])return s.replace(k,OLD[k]);for(var oi=0;oi<OLDP.length;oi++){if(OLDP[oi][0].test(k))return s.replace(k,k.replace(OLDP[oi][0],OLDP[oi][1]))}if(EN[k])return s.replace(k,EN[k]);for(var i=0;i<PAT.length;i++){var m=PAT[i][0].exec(k);if(m){var rr=typeof PAT[i][1]==='function'?PAT[i][1](m):k.replace(PAT[i][0],PAT[i][1]);if(rr!=null)return s.replace(k,rr)}}return null}
