 if(DS.lang()!=='en')return;
 var w=D.createTreeWalker(root,NodeFilter.SHOW_TEXT),n,list=[];while((n=w.nextNode()))if(/[\u0600-\u06FF]/.test(n.nodeValue)&&!(function(){var c=n.parentNode.closest('[lang=en]');return c&&root.contains(c)})()&&!n.parentNode.closest('.ds-sr,option,script'))list.push(n);
