/* KG2 unit practice 1-4 */
var PR={1:{ar:'الأولى',en:'one',lead:['نلعب بالصور والكلمات والعدّ والحكاية مع شخص كبير يقرأ المطلوب. من غير مؤقّت أو درجات أو تسجيل.','We play with pictures, words, counting and a story, with a grown-up who reads the task aloud. No timer, no marks, no recording.'],note:[['دي ١٠ ألعاب أصلية للموقع مبنية على أهداف الوحدة، مش امتحان الوزارة ولا مفتاح إجاباته. الكلمات المصوّرة تنطق المعنى بالعربي ثم الكلمة بالإنجليزي. صوت التعليمات والأسئلة مش متاح هنا، فاقرأ المطلوب للطفل وساعده براحتك.','These are 10 original games for the site, built on the unit goals. They are not the ministry exam or its answer key. Picture words say the meaning in Arabic, then the word in English. The sound for instructions and questions is not available here, so read the task to the child and help at your own pace.'],['الحركات اختيارية في مكان آمن. الحوار والرسم والاختيارات الشخصية من غير إجابة واحدة. جزء اختيار صور السلوك وأسئلة الكتاب اللي مش مدعومة بالحكاية مش موجود هنا.','Movements are optional, in a safe place. Conversation, drawing and personal choices have no single answer. The behaviour picture choice and the book questions not supported by the story are not here.']],book:1,back:'#/kg/2/a/kg2-t1-u1'},
2:{ar:'الثانية',en:'two',lead:['نلعب بالهدوم والصور والعدّ مع شخص كبير يقرأ المطلوب. من غير مؤقّت أو درجات أو تسجيل.','We play with clothes, pictures and counting, with a grown-up who reads the task aloud. No timer, no marks, no recording.'],note:[['دي ٦ ألعاب أصلية للموقع مبنية على أهداف الوحدة، مش امتحان الوزارة ولا مفتاح إجاباته. الكلمات المصوّرة تنطق المعنى بالعربي ثم الكلمة بالإنجليزي. اقرأ المطلوب للطفل وساعده براحتك، صوت التعليمات والأسئلة مش متاح هنا.','These are 6 original games for the site, built on the unit goals. They are not the ministry exam or its answer key. Picture words say the meaning in Arabic, then the word in English. Read the task to the child and help at your own pace. The sound for instructions and questions is not available here.'],['الاختيارات الشخصية من غير إجابة صح وغلط، ومفيش درجات أو تسجيل أو رفع بيانات.','Personal choices have no right or wrong answer, and there are no marks, recordings or uploads.']],book:0,back:'#/kg/2/a/kg2-t1-u1'},
3:{ar:'الثالثة',en:'three',lead:['نلعب بالأيام والكلمات والعدّ مع شخص كبير يقرأ المطلوب. من غير مؤقّت أو درجات أو تسجيل.','We play with days, words and counting, with a grown-up who reads the task aloud. No timer, no marks, no recording.'],note:[['دي ٦ ألعاب أصلية للموقع مبنية على أهداف الوحدة، مش امتحان الوزارة ولا مفتاح إجاباته. الكلمات المصوّرة تنطق المعنى بالعربي ثم الكلمة بالإنجليزي. صوت التعليمات والأسئلة مش متاح هنا، فاقرأ المطلوب للطفل وساعده براحتك.','These are 6 original games for the site, built on the unit goals. They are not the ministry exam or its answer key. Picture words say the meaning in Arabic, then the word in English. The sound for instructions and questions is not available here, so read the task to the child and help at your own pace.'],['الأسئلة عن أمس وبكرة مبنية على يوم بنفترضه في اللعبة، مش اليوم الحقيقي. مفيش أسئلة قصة أو ادعاء صوت حرف منفصل.','The questions about yesterday and tomorrow use a day we pretend in the game, not the real day. There are no story questions and no claim about a separate letter sound.']],book:1,back:'#/kg/2/kg2-t1-u3'},
4:{ar:'الرابعة',en:'four',lead:['نلعب بالوجبات والأوقات والكلمات والعدّ مع شخص كبير يقرأ المطلوب. من غير مؤقّت أو درجات أو تسجيل.','We play with meals, times, words and counting, with a grown-up who reads the task aloud. No timer, no marks, no recording.'],note:[['دي ٦ ألعاب أصلية للموقع مبنية على أهداف الوحدة، مش امتحان الوزارة ولا مفتاح إجاباته. الكلمات المصوّرة تنطق المعنى بالعربي ثم الكلمة بالإنجليزي. صوت التعليمات والأسئلة مش متاح هنا، فاقرأ المطلوب للطفل وساعده براحتك.','These are 6 original games for the site, built on the unit goals. They are not the ministry exam or its answer key. Picture words say the meaning in Arabic, then the word in English. The sound for instructions and questions is not available here, so read the task to the child and help at your own pace.'],['اختيارات الوجبة ووقتها حسب روتين الوحدة، مش مواعيد كل بيت. مفيش مفاتيح لقصة الفاكهة أو المتاهة أو صوت حرف منفصل.','Meal and time choices follow the unit routine, not every home\'s schedule. There are no keys for the fruit story, the maze or a separate letter sound.']],book:1,back:'#/kg/2/kg2-t1-u3'}};
